3: export const jsonType = "export type JSONValue = string | number | boolean | null | JSONValue[] | { [key: string]: JSONValue };\n\n";
4: const parse = text => ts.createSourceFile("gotypes.gen.ts", text, ts.ScriptTarget.Latest, true);
5: const printer = ts.createPrinter({ removeComments: true });
6: const canonical = (node, file) => printer.printNode(ts.EmitHint.Unspecified, node, file);
7: const reference = parse(`export class Reference {
8:  constructor(source: any = {}) {
9:   if ('string' === typeof source) source = JSON.parse(source);
10:  }
11:  convertValues(a: any, classs: any, asMap: boolean = false): any {
12:   if (!a) { return a; }
13:   if (Array.isArray(a)) {
14:    return (a as any[]).map(elem => this.convertValues(elem, classs));
15:   } else if ("object" === typeof a) {
16:    if (asMap) {
17:     for (const key of Object.keys(a)) { a[key] = new classs(a[key]); }
18:     return a;
19:    }
20:    return new classs(a);
21:   }
22:   return a;
23:  }
24: }`);
25: const [referenceConstructor, referenceHelper] = reference.statements[0].members;
26: const requireShape = (condition, message) => {
27:   if (!condition) throw new Error(`Unsupported generated shape: ${message}`);
28: };
29: const identifier = (node, name) => ts.isIdentifier(node) && node.text === name;
30: function walk(node, visit) {
31:   visit(node);
32:   ts.forEachChild(node, child => walk(child, visit));
33: }
