35: // Types refine the existing unchecked materialisation boundary; they do not validate input.
36: export function annotate(raw) {
37:   const file = parse(raw);
38:   requireShape(file.parseDiagnostics.length === 0, "parse failure");
39:   requireShape(file.statements.length > 0, "empty module");
40:   const names = new Set();
41:   for (const cls of file.statements) {
42:     requireShape(ts.isClassDeclaration(cls) && cls.name, "only named classes are supported");
43:     requireShape(cls.name.text !== "JSONValue", "JSONValue name collision");
44:     requireShape(!names.has(cls.name.text), "duplicate class");
45:     names.add(cls.name.text);
46:     requireShape(!cls.heritageClauses && !cls.typeParameters && cls.modifiers?.length === 1 &&
47:       cls.modifiers[0].kind === ts.SyntaxKind.ExportKeyword, "class modifiers");
48:   }
49:   const edits = [];
50:   const replace = (node, text) => edits.push({ start: node.getStart(file), end: node.end, text });
51:   const insert = (offset, text) => edits.push({ start: offset, end: offset, text });
52:   let helpers = 0;
53:   for (const cls of file.statements) {
54:     const properties = new Set();
55:     for (const member of cls.members.filter(ts.isPropertyDeclaration)) {
56:       requireShape(ts.isIdentifier(member.name) && member.type && !member.initializer &&
57:         !member.modifiers && !member.exclamationToken, "public field declaration");
58:       requireShape(!properties.has(member.name.text), "duplicate public field");
59:       properties.add(member.name.text);
60:       walk(member.type, node => requireShape(node.kind !== ts.SyntaxKind.AnyKeyword,
61:         `public field ${cls.name.text}.${member.name.text} requires a Go-owned ts_type`));
62:     }
63:     let constructors = 0, classHelpers = 0;
64:     for (const member of cls.members) {
65:       if (ts.isPropertyDeclaration(member)) continue;
66:       if (ts.isConstructorDeclaration(member)) {
67:         constructors++;
68:         requireShape(!member.modifiers && member.parameters.length === 1 && member.body, "constructor signature");
69:         requireShape(canonical(member.parameters[0], file) === canonical(referenceConstructor.parameters[0], reference), "constructor parameter");
70:         const statements = member.body.statements;
71:         requireShape(statements.length === properties.size + 1 &&
72:           canonical(statements[0], file) === canonical(referenceConstructor.body.statements[0], reference), "JSON constructor preamble or field count");
73:         replace(member.parameters[0].type, "unknown");
74:         const assigned = new Set();
75:         for (const statement of statements.slice(1)) {
76:           requireShape(ts.isExpressionStatement(statement) && ts.isBinaryExpression(statement.expression), "constructor statement");
77:           const assignment = statement.expression;
78:           requireShape(assignment.operatorToken.kind === ts.SyntaxKind.EqualsToken &&
79:             ts.isPropertyAccessExpression(assignment.left) && assignment.left.expression.kind === ts.SyntaxKind.ThisKeyword,
80:             "constructor assignment");
81:           const field = assignment.left.name.text;
82:           requireShape(properties.has(field) && !assigned.has(field), "unknown or repeated field write");
83:           assigned.add(field);
84:           const target = `${cls.name.text}[${JSON.stringify(field)}]`;
85:           const read = node => {
86:             requireShape(ts.isElementAccessExpression(node) && identifier(node.expression, "source") &&
87:               ts.isStringLiteral(node.argumentExpression) && node.argumentExpression.text === field, "source field read");
88:             replace(node.expression, "(source as Record<string, unknown>)");
89:           };
90:           const date = node => {
91:             requireShape(ts.isNewExpression(node) && identifier(node.expression, "Date") &&
92:               !node.typeArguments && node.arguments?.length === 1, "Date transform");
93:             read(node.arguments[0]);
94:             insert(node.arguments[0].end, " as string | number | Date");
95:           };
96:           const rhs = assignment.right;
97:           if (ts.isElementAccessExpression(rhs)) read(rhs);
98:           else if (ts.isNewExpression(rhs)) date(rhs);
99:           else if (ts.isCallExpression(rhs)) {
100:             requireShape(ts.isPropertyAccessExpression(rhs.expression) &&
101:               rhs.expression.expression.kind === ts.SyntaxKind.ThisKeyword && identifier(rhs.expression.name, "convertValues") &&
102:               !rhs.typeArguments && [2, 3].includes(rhs.arguments.length) &&
103:               ts.isIdentifier(rhs.arguments[1]) && names.has(rhs.arguments[1].text) &&
104:               (rhs.arguments.length === 2 || rhs.arguments[2].kind === ts.SyntaxKind.TrueKeyword), "nested conversion");
105:             read(rhs.arguments[0]);
106:           } else if (ts.isBinaryExpression(rhs)) {
107:             requireShape(rhs.operatorToken.kind === ts.SyntaxKind.AmpersandAmpersandToken, "guard operator");
108:             read(rhs.left);
109:             date(rhs.right);
110:             insert(rhs.left.end, ` as ${target}`);
111:             continue;
112:           } else requireShape(false, "constructor transform expression");
113:           insert(rhs.end, ` as ${target}`);
114:         }
115:       } else if (ts.isMethodDeclaration(member)) {
116:         requireShape(canonical(member, file) === canonical(referenceHelper, reference), "convertValues template");
117:         classHelpers++;
118:         helpers++;
119:         replace(member.parameters[0].type, "unknown");
120:         replace(member.parameters[1].type, "new (source: unknown) => unknown");
121:         replace(member.type, "unknown");
122:         walk(member.body, node => {
123:           if (node.kind === ts.SyntaxKind.AnyKeyword) replace(node, "unknown");
124:           if (ts.isElementAccessExpression(node) && identifier(node.expression, "a"))
125:             replace(node.expression, "(a as Record<string, unknown>)");
126:         });
127:       } else requireShape(false, "class member");
128:     }
129:     requireShape(constructors === 1 && classHelpers <= 1, "constructor/helper count");
130:   }
131:   edits.sort((a, b) => a.start - b.start || a.end - b.end);
132:   let end = 0, output = "";
133:   for (const edit of edits) {
134:     requireShape(edit.start >= end && edit.end >= edit.start, "overlapping annotation edits");
135:     output += raw.slice(end, edit.start) + edit.text;
136:     end = edit.end;
137:   }
138:   output = jsonType + output + raw.slice(end);
139:   const result = parse(output);
140:   requireShape(result.parseDiagnostics.length === 0, "annotation parse failure");
141:   walk(result, node => requireShape(node.kind !== ts.SyntaxKind.AnyKeyword, "unhandled explicit-any"));
142:   return { text: output, classes: names.size, helpers };
143: }"}

